{
  "search_complexity": {
    "type": "score",
    "instructions": "How much work will a web search engine like Exa likely need to do to answer this restaurant search well? Judge only the query's qualitative complexity: how common the cuisine or restaurant type is, how well-known and unambiguous the location is, how many OR-alternatives (synonyms, nearby areas) it carries, and whether answering needs deep crawling of many pages. Do not estimate time or perform calculations.",
    "criteria": [
      "1 - Simple lookup of a very common restaurant type in a large, well-known city; likely to finish instantly",
      "2 - Common cuisine in a specific town or neighborhood with at most one extra constraint",
      "3 - Several combined constraints or a few OR-alternatives (synonyms or nearby areas) using common terms",
      "4 - Niche, ambiguous or dish-specific type, a small or ambiguous location, or many OR-alternatives that need semantic matching",
      "5 - Highly complex, multi-intent or ambiguous request; needs deep crawling or multi-step research and will likely take longer"
    ]
  }
}

