// Timestamp before the agent runs. LangSmith treats a run without an end_time as
// still in progress, and without a start_time it cannot compute latency.
return { t: new Date().toISOString() };

// Jev's Score answer is an expected index on 0..4 over the five criteria; convert it to a 1-5 tier.
const ans = <jevcomplexityscorer.answers.search_complexity>;
if (!ans || typeof ans.score !== 'number' || !Number.isFinite(ans.score)) throw new Error('Jev returned no complexity score.');
const tier = Math.min(5, Math.max(1, Math.round(ans.score) + 1));
// Routing table (edit to taste): 1-2 Exa Instant, 3 Exa Fast, 4 Exa Auto, 5 Exa Deep Lite.
const searchType = tier <= 2 ? 'instant' : tier === 3 ? 'fast' : tier === 4 ? 'auto' : 'deep-lite';
const numResults = tier <= 3 ? 8 : 10;
return { t: Date.now(), tier, expectedScore: Math.round((ans.score + 1) * 100) / 100, confidence: ans.confidence, probabilities: ans.probabilities, label: ans.legend && ans.legend[String(tier - 1)], searchType, numResults };

// Final chat message: the restaurants the user asked for, formatted for reading,
// then the total run time. Runs after both paths (rows appended, nothing found).
const t0 = Number((<clockstart.result> || {}).t);
const s = Number.isFinite(t0) ? (Date.now() - t0) / 1000 : null;
const timeLine = 'Total time to execute: ' + (s === null ? 'not available'
  : s < 60 ? s.toFixed(1) + ' seconds' : Math.floor(s / 60) + ' min ' + Math.round(s % 60) + ' s');

const type = String(<parserequest.restaurant_type> || '').trim();
const loc = String(<parserequest.location> || '').trim();
const list = Array.isArray(<restaurantfinder.restaurants>) ? <restaurantfinder.restaurants> : [];
const summary = String(<restaurantfinder.summary> || '');
const missing = v => !v || /^not\s+listed$/i.test(String(v).trim());

let answer;
if (!list.length) {
  answer = 'Sorry, I could not find any ' + type + ' restaurants near ' + loc +
    '. Try a nearby city or a broader type of food.';
} else {
  // The summary may be one line per restaurant or one paragraph: split on lines and sentences.
  const lines = summary.split(/\n+|(?<=[.!?])\s+(?=[A-Z0-9*])/).map(x => x.trim()).filter(Boolean);
  const used = new Set();
  const items = list.map((r, i) => {
    const name = String(r.restaurant_name || 'Unnamed restaurant').trim();
    const k = lines.findIndex((l, j) => !used.has(j) && l.toLowerCase().includes(name.toLowerCase()));
    let blurb = '';
    if (k >= 0) { used.add(k); blurb = lines[k]; }
    blurb = blurb.replace(/^(\d+[.)]|[-*])\s*/, '').replace(/\*\*/g, '').trim();
    if (blurb.toLowerCase().startsWith(name.toLowerCase())) blurb = blurb.slice(name.length).replace(/^[\s,:\u2013\u2014-]+/, '').trim();
    const out = [(i + 1) + '. **' + name + '**' + (blurb ? ' - ' + blurb : '')];
    if (!missing(r.address)) out.push('   - Address: ' + r.address);
    if (!missing(r.phone)) out.push('   - Phone: ' + r.phone);
    if (!missing(r.hours)) out.push('   - Hours: ' + r.hours);
    return out.join('\n');
  });
  const extra = lines.filter((_, j) => !used.has(j));
  answer = 'Here ' + (list.length === 1 ? 'is 1 ' : 'are ' + list.length + ' ') + type +
    ' restaurant' + (list.length === 1 ? '' : 's') + ' near ' + loc + ':\n\n' +
    items.join('\n') + (extra.length ? '\n\n' + extra.join('\n') : '');
}
return answer + '\n\n' + timeLine;

// Last chat message: which models and search blocks this workflow uses, with the
// time each of them took in this run ("did not run" when its path was skipped), and
// the question types each Jev Agent uses.
// Block list is fixed text: update it if Agent or Exa blocks are added, removed or change model.
// Jev Agent times are the model call time each Agent reports (providerTiming.duration).
// Exa blocks and the structured-output Gemini Agents expose no timing field, so their
// time is measured between the Function blocks on either side of them (~ prefix;
// includes a few tens of ms of block overhead). Only one Exa block runs per request.
// Jev question types (choice, score, noul) are counted from the questions actually sent
// to each Jev Agent in this run; when a Jev Agent did not run, its configured types are shown.
const fmt = ms => (typeof ms !== 'number' || !Number.isFinite(ms) || ms < 0) ? 'did not run'
  : ms < 1000 ? Math.round(ms) + ' ms' : (ms / 1000).toFixed(1) + ' s';
const agentMs = pt => (pt && typeof pt.duration === 'number') ? pt.duration : null;
const ts = x => (x && x.t != null) ? (typeof x.t === 'number' ? x.t : Date.parse(x.t)) : NaN;
const gap = (a, b) => { const d = ts(b) - ts(a); return Number.isFinite(d) ? d : null; };

const TYPES = ['choice', 'score', 'noul'];
const countTypes = q => {
  const c = {};
  if (q && typeof q === 'object') for (const v of Object.values(q)) {
    const t = v && typeof v.type === 'string' ? v.type : null;
    if (t) c[t] = (c[t] || 0) + 1;
  }
  return c;
};
const order = c => [...TYPES.filter(t => c[t]), ...Object.keys(c).filter(t => !TYPES.includes(t))];
const typeText = (ms, q, configured) => {
  const c = countTypes(q);
  if (ms !== null && Object.keys(c).length) {
    return 'question types: ' + order(c).map(t => t + ' (' + c[t] + ' question' + (c[t] === 1 ? '' : 's') + ')').join(', ');
  }
  return 'question types: ' + configured.join(', ');
};
// jevComplexityScorer's questions are static in the block (one score question: search_complexity).
const complexityQuestions = { search_complexity: { type: 'score' } };

const jev = [
  ['jevQueryOptimizer', agentMs(<jevqueryoptimizer.providerTiming>), <buildjevcandidates.result.questions>, ['noul']],
  ['jevComplexityScorer', agentMs(<jevcomplexityscorer.providerTiming>), complexityQuestions, ['score']],
  ['jevResultGuard', agentMs(<jevresultguard.providerTiming>), <normalizeresults.result.guardQuestions>, ['noul']]
];
const usedTypes = new Set(jev.flatMap(j => j[3]));
const norm = <normalizeresults.result>;
const used = norm && norm.searchTypeUsed;
const exaMs = gap(<routebycomplexity.result>, norm);
const exa = [
  ['exaInstant', 'instant'],
  ['webSearch (Exa Fast)', 'fast'],
  ['exaAuto', 'auto'],
  ['exaDeepLite', 'deep-lite']
].map(([n, mode]) => [n, used === mode ? exaMs : null]);
const other = [
  ['parseRequest', 'gemini-3.5-flash-lite', gap(<clockstart.result>, <markstart.result>)],
  ['restaurantFinder', 'gemini-3.5-flash-lite', gap(<filterresults.result>, <buildtelemetry.result>)]
];
return [
  'About this workflow (time each block took in this run):',
  '- Agent blocks using the Jev model (' + jev.length + '):',
  ...jev.map(([n, ms, q, cfg]) => '  - ' + n + ': ' + fmt(ms) + ' (' + typeText(ms, q, cfg) + ')'),
  '  Jev question types: ' + TYPES.map(t => t + (usedTypes.has(t) ? '' : ' (not used)')).join(', '),
  '- Exa blocks (' + exa.length + ', one runs per request):',
  ...exa.map(([n, ms]) => '  - ' + n + ': ' + (ms === null ? 'did not run' : '~' + fmt(ms))),
  '- Agent blocks not using Jev (' + other.length + '):',
  ...other.map(([n, m, ms]) => '  - ' + n + ' (' + m + '): ' + (ms === null ? 'did not run' : '~' + fmt(ms)))
].join('\n');

const list = <restaurantFinder.restaurants> || [];
const runDate = new Date().toISOString().slice(0, 10);
const source = String(<start.metadata.executionType> || 'manual').toLowerCase();

// The model sometimes echoes a source's own wording for a gap ("Not provided on
// the page", "not specified") instead of the exact "Not listed" the prompt asks
// for. Normalize deterministically here so the table has one consistent value.
function clean(v) {
  const s = (v === undefined || v === null) ? '' : String(v).trim();
  if (!s) return 'Not listed';
  if (/^not\s+(listed|provided|specified|available|given|found)\b/i.test(s)) return 'Not listed';
  if (/^(n\/a|none|unknown|unavailable)$/i.test(s)) return 'Not listed';
  return s;
}

// Jev run metrics saved on every row.
const route = <routebycomplexity.result> || {};
const t0 = Number((<clockstart.result> || {}).t);
const totalTimeSeconds = Number.isFinite(t0) ? Math.round((Date.now() - t0) / 100) / 10 : null;

const seen = new Set();
const rows = [];
for (const r of list) {
  const name = (r && r.restaurant_name ? String(r.restaurant_name) : '').trim();
  if (!name) continue;
  const key = name.toLowerCase();
  if (seen.has(key)) continue;
  seen.add(key);
  rows.push({
    run_date: runDate,
    restaurant_type: <parseRequest.restaurant_type>,
    location: <parseRequest.location>,
    restaurant_name: name,
    address: clean(r.address),
    phone: clean(r.phone),
    hours: clean(r.hours),
    source: source,
    jev_complexity: typeof route.tier === 'number' ? route.tier : null,
    search_mode: route.searchType || null,
    total_time_seconds: totalTimeSeconds
  });
  if (rows.length >= 5) break;
}
return rows;

// LangSmith trace for this run.
//
// IMPORTANT: restaurantFinder uses a responseFormat, which REPLACES the agent's
// default outputs with the schema's top-level fields. The only readable fields are
// restaurants and summary — providerTiming, model, tokens, cost and toolCalls do
// NOT exist on this block and referencing any of them fails the run at resolve
// time (this is what broke the live chat). The agent also has no tools any more,
// so there are no tool calls to report.
//
// Timing comes from markStart (stamped just before the search) and the clock here,
// which brackets search + format. Nothing below is invented.
const startIso = (<markstart.result> || {}).t || new Date().toISOString();
const startMs  = new Date(startIso).getTime();
const endMs    = Date.now();

const list    = <restaurantfinder.restaurants> || [];
const summary = <restaurantfinder.summary> || '';

// no crypto.randomUUID in this sandbox
function uuid() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
    const r = Math.random() * 16 | 0;
    return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
  });
}
function pad(n, w) { return String(n).padStart(w, '0'); }
// dotted_order format, confirmed against this account's own runs:
//   YYYYMMDDTHHMMSSffffffZ<uuid>
function seg(ms, id) {
  const d = new Date(ms);
  return d.getUTCFullYear() + pad(d.getUTCMonth() + 1, 2) + pad(d.getUTCDate(), 2) + 'T'
       + pad(d.getUTCHours(), 2) + pad(d.getUTCMinutes(), 2) + pad(d.getUTCSeconds(), 2)
       + pad(d.getUTCMilliseconds(), 3) + '000Z' + id;
}
const iso = function (ms) { return new Date(ms).toISOString(); };

const rootId  = uuid();
const rootDot = seg(startMs, rootId);

const post = [{
  id: rootId, trace_id: rootId, dotted_order: rootDot,
  name: 'find-a-restaurant', run_type: 'chain',
  start_time: iso(startMs), end_time: iso(endMs),
  inputs:  { restaurant_type: <parseRequest.restaurant_type>, location: <parseRequest.location>, chat_message: <start.input> },
  outputs: { count: list.length, restaurants: list, summary: summary },
  tags: ['find-a-restaurant', 'sim', 'agent'],
  extra: { metadata: {
    sim_workflow_id: '86b5037b-5508-49d7-a98c-df10b57cd6ae',
    execution_id: <start.metadata.executionId>,
    execution_type: <start.metadata.executionType>,
    duration_ms: endMs - startMs
  } }
}];

return { post: post, spans: post.length, root: rootId, t: endMs };  // t: restaurantFinder just finished (blockInventory)

// Terminator for the telemetry branch. errorEnabled only creates an error HANDLE;
// if that handle has no outgoing edge the error still fails the whole execution.
// Wiring both handles here contains a LangSmith outage so the main path survives.
return { telemetry: 'attempted' };

// Post-search guardrail: keep only results Jev judges relevant.
const items = <normalizeresults.result.items> || [];
const answers = <jevresultguard.answers> || {};
const KEEP_AT = 0.5;
const scored = items.map((it, i) => {
  const v = answers['result_' + (i + 1)] && answers['result_' + (i + 1)].noul;
  if (typeof v !== 'number' || !Number.isFinite(v)) throw new Error('Jev returned no guardrail probability for ' + it.url);
  return Object.assign({}, it, { jevRelevance: Math.round(v * 1000) / 1000 });
});
const kept = scored.filter(x => x.jevRelevance >= KEEP_AT).sort((a, b) => b.jevRelevance - a.jevRelevance);
const rejected = scored.filter(x => x.jevRelevance < KEEP_AT).map(x => ({ title: x.title, url: x.url, jevRelevance: x.jevRelevance }));
const any = answers.any_relevant && answers.any_relevant.noul;
return { t: Date.now(), kept, keptCount: kept.length, rejected, rejectedCount: rejected.length, screened: items.length, anyRelevant: typeof any === 'number' ? Math.round(any * 1000) / 1000 : null };

// First line shown on the chat page while the Jev search runs.
const msg = String(<start.input> || '').trim() ||
  [String(<start.RestaurantType> || '').trim(), String(<start.location> || '').trim()].filter(Boolean).join(' in ');
return 'Please wait. Search for ' + msg;

// Second chat status line, shown once Jev has planned the search.
const r = <routebycomplexity.result>;
const p = <buildsearchpayload.result>;
const modes = { instant: 'Exa Instant', fast: 'Exa Fast', auto: 'Exa Auto', 'deep-lite': 'Exa Deep Lite' };
const conf = typeof r.confidence === 'number' ? ' (' + Math.round(r.confidence * 100) + '% confident)' : '';
const extraTerms = (p.terms || []).map(t => t.value);
return 'Jev search plan: complexity ' + r.tier + ' of 5' + conf + ' → ' + (modes[r.searchType] || r.searchType) + ' search, ' + r.numResults + ' results.' +
  ' Area: ' + (p.approvedAreas || []).join(', ') + '.' +
  (extraTerms.length ? ' Also searching for: ' + extraTerms.join(', ') + '.' : '');
